// The icon table of the game's five standard modules, generated by tools/catalog/generate.mjs. Exported on its own as
// `@face/catalog/icons/standard`: only the desktop main process needs it.

import data from "../data/icons-2.1.24.json" with { type: "json" };
import { parseIconTable, type IconTable } from "./iconTable.ts";

let cached: IconTable | undefined;

/** Which image files of Factorio 2.1.24 make up each icon the standard catalog refers to. The result is shared; treat it as immutable. */
export function loadStandardIconTable(): IconTable {
  cached ??= parseIconTable(data);
  return cached;
}
